import json, os, subprocess, time, hashlib
from pathlib import Path

home=Path("/Users/steventran")
candidates=[
    home/"do-again",
    home/"jobpipe",
    home/"Sonary",
    home/"sonary",
]

def run(cwd,args):
    p=subprocess.run(args,cwd=cwd,text=True,capture_output=True,check=False)
    return {"rc":p.returncode,"stdout":p.stdout[-8000:],"stderr":p.stderr[-4000:]}

def file_sha(p):
    if not p.is_file(): return None
    h=hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda:f.read(65536),b""):
            h.update(chunk)
    return h.hexdigest()

def parse_toml_text(path):
    if not path.is_file(): return {}
    import tomllib
    try:
        return tomllib.loads(path.read_text())
    except Exception as e:
        return {"_error":repr(e)}

projects=[]
for p in candidates:
    if not p.is_dir():
        continue
    git=run(p,["git","rev-parse","--show-toplevel"])
    if git["rc"]!=0:
        continue
    root=Path(git["stdout"].strip())
    if any(x.get("root")==str(root) for x in projects):
        continue
    cfg=parse_toml_text(root/"do-again.toml")
    section=cfg.get("do_again",{}) if isinstance(cfg,dict) else {}
    projects.append({
        "name":root.name,
        "root":str(root),
        "head":run(root,["git","rev-parse","HEAD"])["stdout"].strip(),
        "branch":run(root,["git","branch","--show-current"])["stdout"].strip(),
        "status":run(root,["git","status","--porcelain=v1"])["stdout"],
        "config":{
            "continuous":section.get("continuous"),
            "report_stalls":section.get("report_stalls"),
            "idle_seconds":section.get("idle_seconds"),
            "recovery_seconds":section.get("recovery_seconds"),
            "browser_enabled":section.get("browser_enabled"),
        },
    })

# Enumerate installed per-project runtime dirs read-only.
runtime_root=home/".do_again"/"projects"
runtime_entries=[]
if runtime_root.is_dir():
    for d in sorted(runtime_root.iterdir()):
        if not d.is_dir(): continue
        state=d/"state"
        runtime=d/"runtime"
        control=d/"control"
        # collect project path hints from service metadata/config files
        hints={}
        for rel in ["repo_path","project.json","runtime.json","service.json","config.json"]:
            q=state/rel
            if q.is_file():
                try: hints[rel]=q.read_text()[:4000]
                except Exception: pass
        runtime_entries.append({
            "id":d.name,
            "runtime_exists":runtime.is_dir(),
            "liveness_py":(runtime/"do_again"/"service"/"liveness.py").is_file() or (runtime/"src"/"do_again"/"service"/"liveness.py").is_file(),
            "daemon_sha": file_sha(runtime/"do_again"/"service"/"daemon.py") or file_sha(runtime/"src"/"do_again"/"service"/"daemon.py"),
            "liveness_sha": file_sha(runtime/"do_again"/"service"/"liveness.py") or file_sha(runtime/"src"/"do_again"/"service"/"liveness.py"),
            "outbox_files": sorted([x.name for x in (state/"browser_outbox").glob("*.json")]) if (state/"browser_outbox").is_dir() else [],
            "liveness_state": json.loads((state/"liveness.json").read_text()) if (state/"liveness.json").is_file() else None,
            "hints":hints,
        })

# Process inventory: only do-again/python processes, sanitized command line.
ps=run(home,["ps","-axo","pid=,ppid=,etime=,command="])
proc=[]
for line in ps["stdout"].splitlines():
    low=line.lower()
    if "do_again" in low or "do-again" in low:
        parts=line.strip().split(None,3)
        if len(parts)>=4:
            pid,ppid,etime,cmd=parts
            proc.append({"pid":pid,"ppid":ppid,"etime":etime,"cmd":cmd[:600]})

# Read control worktrees for pending requests/claims/receipts. No content bodies beyond metadata.
for ent in runtime_entries:
    d=runtime_root/ent["id"]
    possible=[d/"control", d/"control_worktree", d/"operator-control"]
    control=next((x for x in possible if x.is_dir()),None)
    ent["control_path"]=str(control) if control else None
    if control:
        req=control/"automation/do_again/requests"
        rec=control/"automation/do_again/receipts"
        claims=control/"automation/do_again/claims"
        req_ids=sorted(x.stem for x in req.glob("*.json")) if req.is_dir() else []
        rec_ids={x.stem for x in rec.glob("*.json")} if rec.is_dir() else set()
        ent["pending_request_ids"]=[x for x in req_ids if x not in rec_ids][-20:]
        ent["claim_ids"]=sorted(x.stem for x in claims.glob("*.json"))[-20:] if claims.is_dir() else []
        ent["latest_receipts"]=sorted(rec_ids)[-20:]

print(json.dumps({
    "timestamp":time.time(),
    "projects":projects,
    "runtime_entries":runtime_entries,
    "processes":proc,
},indent=2,sort_keys=True))
